        update_game(snake, food, width, height);

        // Actualiza la pantalla
        render_game(snake, food, score, renderer);

        end_time = SDL_GetTicks();
        frame_delay = 1000 / fps - (end_time - start_time);

        if (frame_delay > 0) {
            SDL_Delay(frame_delay);
        }
    }
}
```

9. Crea una función para inicializar el juego, incluyendo crear la serpiente y la comida, crear la pantalla, cargar las imágenes, y llamar a la función de ciclo de juego.

```c
void start_game(int width, int height, int fps) {
    SDL_Window *window = SDL_CreateWindow(
        "Snake",
        SDL_WINDOWPOS_CENTERED_DISPLAY(0),
        SDL_WINDOWPOS_CENTERED_DISPLAY(0),
        width,
        height,
        SDL_WINDOW_SHOWN
    );

    if (window == NULL) {
        printf("Error: %s\n", SDL_GetError());
        return;
    }

    SDL_Renderer *renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);

    if (renderer == NULL) {
        printf("Error: %s\n", SDL_GetError());
        SDL_DestroyWindow(window);
        return;
    }

    // Carga las imágenes
    SDL_Texture *head_texture = SDL_CreateTextureFromSurface(renderer, SDL_LoadBMP("head.bmp"));
    SDL_Texture *body_texture = SDL_CreateTextureFromSurface(renderer, SDL_LoadBMP("body.bmp"));
    SDL_Texture *food_texture = SDL_CreateTextureFromSurface(renderer, SDL_LoadBMP("food.bmp"));

    if (head_texture == NULL || body_texture == NULL || food_texture == NULL) {
        printf("Error: %s\n", SDL_GetError());
        SDL_DestroyRenderer(renderer);
        SDL_DestroyWindow(window);
        return;
    }

    Snake snake = {width / 2, height / 2, 'r', 1, malloc(sizeof(int))}; // Inicializa la serpiente con una sola parte
    snake.body[0] = (SDL_Point){snake.x, snake.y};

    Food food = {rand() % (width - 20) + 10, rand() % (height - 20) + 10}; // Inicializa la comida en una posición aleatoria

    game_loop(&snake, &food, width, height, fps, renderer, head_texture, body_texture, food_texture);

    SDL_DestroyTexture(head_texture);
    SDL_DestroyTexture(body_texture);
    SDL_DestroyTexture(food_texture);

    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
}
```

10. Finalmente, llamar a la función de inicio del juego para comenzar el juego.

```c
int main() {
    start_game(600, 400, 60);
    return 0;
}
```

